CREATE TABLE reconciliation_cases (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), purchase_order_id uuid NOT NULL REFERENCES purchase_orders(id), invoice_number text NOT NULL, invoice_amount numeric(19,4) NOT NULL CHECK (invoice_amount >= 0), currency char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), vendor_name text NOT NULL, match_status text NOT NULL CHECK (match_status IN ('MATCHED', 'REVIEW_REQUIRED', 'EXCEPTION')), confidence numeric(5,4) NOT NULL CHECK (confidence >= 0 AND confidence <= 1), explanation text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewed_by uuid REFERENCES users(id), decision text CHECK (decision IN ('APPROVED', 'REJECTED')));
CREATE INDEX reconciliation_cases_queue_idx ON reconciliation_cases(organization_id, match_status, created_at DESC);
ALTER TABLE reconciliation_cases ENABLE ROW LEVEL SECURITY; ALTER TABLE reconciliation_cases FORCE ROW LEVEL SECURITY;
CREATE POLICY reconciliation_cases_tenant_scope ON reconciliation_cases USING (organization_id = current_setting('app.organization_id', true)::uuid) WITH CHECK (organization_id = current_setting('app.organization_id', true)::uuid);
